FROM `shop_manager`
WHERE shop_id = #{shopId}
  AND phone = #{phone}
  AND head_manager = 1

select * from `shop_manager`
where shop_id=#{param.searchId}

    and phone LIKE CONCAT('%', #{param.keyword}, '%')

